SELECT * FROM ma_source WHERE account_id = #{accountId} AND type = #{type}
    AND status = 'ACTIVE'

    AND (created_at, source_id) < (#{beforeTime}, #{beforeId})

ORDER BY created_at DESC, source_id DESC LIMIT #{limit}

mapper.update:
UPDATE ma_source SET current_version = #{newVersion}, title = #{title}
WHERE account_id = #{accountId} AND source_id = #{sourceId}
    AND status = 'ACTIVE' AND current_version = #{oldVersion}

UPDATE ma_source_version SET status = #{status}
WHERE source_id = #{sourceId} AND version = #{version} AND status = 'INDEX_PENDING'
    AND index_revision = #{expectedIndexRevision}
    AND EXISTS (SELECT 1 FROM ma_source s WHERE s.source_id = #{sourceId}
        AND s.account_id = #{accountId} AND s.status = 'ACTIVE'
        AND s.current_version = #{version})

UPDATE ma_source_version SET status = 'INDEX_PENDING', index_revision = index_revision + 1
WHERE source_id = #{sourceId} AND version = #{version}
    AND status IN ('READY','FAILED') AND index_revision = #{expectedIndexRevision}
    AND EXISTS (SELECT 1 FROM ma_source s WHERE s.source_id = #{sourceId}
        AND s.account_id = #{accountId} AND s.status = 'ACTIVE'
        AND s.current_version = #{version})
